-- Open Agents: initial schema.
-- Ids are UUIDv7 generated by the application (sortable by time, known before insert = idempotent retries).
-- Model and invariants: docs/data-model.md, docs/threads.md.

-- ---------------------------------------------------------------- identities

CREATE TABLE users (
  id            uuid PRIMARY KEY,
  email         text NOT NULL UNIQUE,
  display_name  text NOT NULL,
  role          text NOT NULL CHECK (role IN ('admin', 'user')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  disabled_at   timestamptz
);

CREATE TABLE workers (
  id               uuid PRIMARY KEY,
  owner_user_id    uuid REFERENCES users (id),          -- NULL = shared worker
  name             text NOT NULL,
  os               text NOT NULL DEFAULT '',
  arch             text NOT NULL DEFAULT '',
  version          text NOT NULL DEFAULT '',
  credential_hash  text NOT NULL,
  capabilities     jsonb NOT NULL DEFAULT '{}',          -- last Hello: providers, profiles, allowed roots
  last_seen_at     timestamptz,
  revoked_at       timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  archived_at      timestamptz
);

-- Which gateway instance holds the worker's stream. epoch fences stale instances.
CREATE TABLE worker_connections (
  worker_id     uuid PRIMARY KEY REFERENCES workers (id),
  instance_id   text NOT NULL,
  epoch         bigint NOT NULL,
  connected_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE enrollment_tokens (
  id          uuid PRIMARY KEY,
  token_hash  text NOT NULL UNIQUE,
  created_by  uuid NOT NULL REFERENCES users (id),
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz,
  worker_id   uuid REFERENCES workers (id)
);

-- ---------------------------------------------------------------- projects

CREATE TABLE projects (
  id             uuid PRIMARY KEY,
  owner_user_id  uuid NOT NULL REFERENCES users (id),
  name           text NOT NULL,
  slug           text NOT NULL,
  description    text NOT NULL DEFAULT '',
  created_at     timestamptz NOT NULL DEFAULT now(),
  archived_at    timestamptz
);
CREATE UNIQUE INDEX projects_owner_slug ON projects (owner_user_id, slug) WHERE archived_at IS NULL;

-- Where a project physically exists: a directory on a worker (the same repo may live on several machines).
CREATE TABLE project_workspaces (
  id           uuid PRIMARY KEY,
  project_id   uuid NOT NULL REFERENCES projects (id),
  worker_id    uuid NOT NULL REFERENCES workers (id),
  root_path    text NOT NULL,                            -- absolute, must be inside the worker's allowed roots
  label        text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz,
  UNIQUE (id, project_id, worker_id)                     -- target of the composite FK from threads
);
CREATE UNIQUE INDEX project_workspaces_location
  ON project_workspaces (project_id, worker_id, root_path) WHERE archived_at IS NULL;

-- ---------------------------------------------------------------- agents (templates, no placement)

CREATE TABLE agents (
  id               uuid PRIMARY KEY,
  scope            text NOT NULL CHECK (scope IN ('global', 'private')),
  owner_user_id    uuid REFERENCES users (id),
  kind             text NOT NULL CHECK (kind IN ('sdk', 'chat')),
  provider         text NOT NULL CHECK (provider IN ('claude', 'codex', 'anthropic', 'openai')),
  name             text NOT NULL,
  slug             text NOT NULL,
  description      text NOT NULL DEFAULT '',
  model            text NOT NULL DEFAULT '',
  instructions     text NOT NULL DEFAULT '',
  permission_mode  text NOT NULL DEFAULT 'ask' CHECK (permission_mode IN ('ask', 'accept_edits', 'read_only', 'full_auto')),
  config           jsonb NOT NULL DEFAULT '{}',
  revision         integer NOT NULL DEFAULT 1,           -- bumped on edit; threads keep the revision they started with
  created_by       uuid NOT NULL REFERENCES users (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  archived_at      timestamptz,
  CONSTRAINT agents_scope_owner CHECK ((scope = 'private' AND owner_user_id IS NOT NULL) OR (scope = 'global' AND owner_user_id IS NULL)),
  CONSTRAINT agents_kind_provider CHECK ((kind = 'sdk' AND provider IN ('claude', 'codex')) OR (kind = 'chat' AND provider IN ('anthropic', 'openai')))
);
CREATE UNIQUE INDEX agents_global_slug ON agents (slug) WHERE scope = 'global' AND archived_at IS NULL;
CREATE UNIQUE INDEX agents_private_slug ON agents (owner_user_id, slug) WHERE scope = 'private' AND archived_at IS NULL;

-- ---------------------------------------------------------------- threads

-- A thread is one durable conversation bound for life to one provider thread, one worker and one directory.
-- Side threads hang under a main thread, share its directory and may fork its history.
CREATE TABLE threads (
  id                     uuid PRIMARY KEY,
  project_id             uuid NOT NULL REFERENCES projects (id),
  owner_user_id          uuid NOT NULL REFERENCES users (id),
  kind                   text NOT NULL CHECK (kind IN ('main', 'side')),
  parent_thread_id       uuid REFERENCES threads (id),
  root_thread_id         uuid NOT NULL REFERENCES threads (id),
  depth                  smallint NOT NULL DEFAULT 0,
  origin                 text NOT NULL DEFAULT 'user' CHECK (origin IN ('user', 'agent')),
  spawned_by_call_id     uuid,                           -- origin = agent: the spawn_thread call (FK added with agent_bus_calls)
  -- Who answers this thread's permission prompts and questions: the user, or the parent thread's agent
  -- (answer_interaction). The user can always answer in the UI as well.
  interaction_route      text NOT NULL DEFAULT 'human' CHECK (interaction_route IN ('human', 'parent')),
  agent_id               uuid REFERENCES agents (id),
  agent_revision         integer,
  runtime                text NOT NULL CHECK (runtime IN ('worker', 'gateway')),
  provider               text NOT NULL CHECK (provider IN ('claude', 'codex', 'anthropic', 'openai')),
  provider_profile_id    text,                           -- ProviderProfile.id on the worker; NULL = native
  worker_id              uuid REFERENCES workers (id),
  workspace_id           uuid,
  cwd                    text,                           -- absolute; equals or is below the workspace root
  provider_thread_id     text,                           -- Claude session id / Codex thread id, set by THREAD_READY
  fork_source_thread_id  uuid REFERENCES threads (id),
  fork_after_turn_id     uuid,                           -- NULL with a source = fork at the source's latest completed turn
  settings               jsonb NOT NULL DEFAULT '{}',    -- model, instructions, permission mode (snapshot, may change between turns)
  status                 text NOT NULL DEFAULT 'creating'
                           CHECK (status IN ('creating', 'idle', 'running', 'waiting_input', 'interrupted', 'failed', 'archived')),
  title                  text NOT NULL DEFAULT '',
  last_seq               bigint NOT NULL DEFAULT 0,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  archived_at            timestamptz,

  FOREIGN KEY (workspace_id, project_id, worker_id) REFERENCES project_workspaces (id, project_id, worker_id),
  CONSTRAINT threads_main_has_no_parent CHECK ((kind = 'main') = (parent_thread_id IS NULL)),
  CONSTRAINT threads_main_is_root CHECK ((kind = 'main') = (root_thread_id = id)),
  CONSTRAINT threads_main_depth CHECK ((kind = 'main') = (depth = 0)),
  -- Two levels: the main thread orchestrates, side threads do not start further side threads.
  CONSTRAINT threads_max_depth CHECK (depth <= 1),
  CONSTRAINT threads_fork_only_side CHECK (kind = 'side' OR fork_source_thread_id IS NULL),
  CONSTRAINT threads_fork_point_needs_source CHECK (fork_after_turn_id IS NULL OR fork_source_thread_id IS NOT NULL),
  CONSTRAINT threads_agent_origin CHECK ((origin = 'agent') = (spawned_by_call_id IS NOT NULL)),
  CONSTRAINT threads_parent_route CHECK (interaction_route = 'human' OR kind = 'side'),
  CONSTRAINT threads_runtime_placement CHECK (
    (runtime = 'worker' AND provider IN ('claude', 'codex')
       AND worker_id IS NOT NULL AND workspace_id IS NOT NULL AND cwd IS NOT NULL)
    OR
    (runtime = 'gateway' AND provider IN ('anthropic', 'openai')
       AND worker_id IS NULL AND workspace_id IS NULL AND cwd IS NULL AND provider_profile_id IS NULL)
  )
);
CREATE INDEX threads_project ON threads (project_id, created_at DESC) WHERE kind = 'main';
CREATE INDEX threads_root ON threads (root_thread_id);
CREATE INDEX threads_worker_active ON threads (worker_id) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX threads_provider_thread ON threads (worker_id, provider, provider_thread_id) WHERE provider_thread_id IS NOT NULL;

-- One input -> one turn. Also the durable queue: at most one running turn per thread.
-- Turns are started by the user, by the agent bus, or by the provider itself
-- (wake-up after a background task, automatic recovery of an interrupted turn); see docs/execution.md.
CREATE TABLE turns (
  id                 uuid PRIMARY KEY,                   -- gateway for user/agent_bus, worker for provider/recovery
  thread_id          uuid NOT NULL REFERENCES threads (id),
  ordinal            integer NOT NULL,
  status             text NOT NULL DEFAULT 'queued'
                       CHECK (status IN ('queued', 'running', 'completed', 'interrupted', 'failed', 'cancelled')),
  trigger            text NOT NULL CHECK (trigger IN ('user', 'agent_bus', 'schedule', 'interaction', 'goal', 'provider', 'recovery')),
  author_user_id     uuid REFERENCES users (id),
  agent_call_id      uuid,                               -- trigger = agent_bus (FK added with agent_bus_calls)
  schedule_id        uuid,                               -- trigger = schedule (FK added with schedules)
  interaction_request_id uuid,                           -- trigger = interaction: a side thread asks the parent (FK added later)
  -- Goal the turn works toward (any trigger; native engines continue as provider turns).
  -- trigger = goal: continuation started by the platform engine. FK added with goals.
  goal_id            uuid,
  -- Agent-to-agent chain length: 0 for human input and provider wake-ups, +1 per bus hop (docs/agent-bus.md).
  hops               smallint NOT NULL DEFAULT 0 CHECK (hops BETWEEN 0 AND 16),
  resumes_turn_id    uuid,                               -- trigger = recovery: the interrupted turn it continues
  resume_reason      text,
  client_request_id  text,
  input              jsonb NOT NULL,
  model              text NOT NULL DEFAULT '',
  provider_turn_ref  text,                               -- Codex turn id / Claude message uuid: fork point at the provider
  first_seq          bigint,
  last_seq           bigint,
  usage              jsonb,
  error              text,
  interrupt_reason   text,
  lease_owner        text,                               -- gateway runtime only: instance executing the turn
  lease_until        timestamptz,
  attempt            integer NOT NULL DEFAULT 0,
  queued_at          timestamptz NOT NULL DEFAULT now(),
  started_at         timestamptz,
  completed_at       timestamptz,
  UNIQUE (thread_id, ordinal),
  UNIQUE (id, thread_id),
  FOREIGN KEY (resumes_turn_id, thread_id) REFERENCES turns (id, thread_id),
  CONSTRAINT turns_user_author CHECK ((trigger = 'user') = (author_user_id IS NOT NULL)),
  CONSTRAINT turns_agent_bus_call CHECK ((trigger = 'agent_bus') = (agent_call_id IS NOT NULL)),
  CONSTRAINT turns_schedule CHECK ((trigger = 'schedule') = (schedule_id IS NOT NULL)),
  CONSTRAINT turns_interaction CHECK ((trigger = 'interaction') = (interaction_request_id IS NOT NULL)),
  CONSTRAINT turns_goal CHECK (trigger <> 'goal' OR goal_id IS NOT NULL),
  -- Human input and provider wake-ups reset the agent chain; bus turns extend it; schedules and
  -- interaction prompts inherit the hops of whatever created them.
  CONSTRAINT turns_hops_by_trigger CHECK (
    -- Goal continuations are bounded by the goal's budgets, not by hops.
    (trigger IN ('user', 'goal', 'provider', 'recovery') AND hops = 0)
    OR (trigger = 'agent_bus' AND hops > 0)
    OR trigger IN ('schedule', 'interaction')
  ),
  CONSTRAINT turns_recovery_link CHECK ((trigger = 'recovery') = (resumes_turn_id IS NOT NULL)),
  -- Provider-started turns exist only once the worker reports them; they are never queued by the gateway.
  CONSTRAINT turns_provider_not_queued CHECK (trigger NOT IN ('provider', 'recovery') OR status <> 'queued'),
  CONSTRAINT turns_completed_has_seq CHECK (status <> 'completed' OR last_seq IS NOT NULL)
);
CREATE UNIQUE INDEX turns_one_running ON turns (thread_id) WHERE status = 'running';
CREATE UNIQUE INDEX turns_client_request ON turns (thread_id, client_request_id) WHERE client_request_id IS NOT NULL;
CREATE INDEX turns_queued ON turns (thread_id, ordinal) WHERE status = 'queued';

ALTER TABLE threads
  ADD FOREIGN KEY (fork_after_turn_id, fork_source_thread_id) REFERENCES turns (id, thread_id);

-- Transcript: the single ordered timeline of a thread (docs/transcript.md).
-- Append-only. seq is assigned by the gateway, so worker events and platform events
-- (user input, permission decisions, agent bus, notices) share one order.
-- A fork reads the source prefix instead of copying it (see thread_timeline).
CREATE TABLE thread_events (
  thread_id    uuid NOT NULL REFERENCES threads (id),
  seq          bigint NOT NULL CHECK (seq > 0),
  event_id     uuid NOT NULL,                          -- idempotency key, set where the event originated
  origin       text NOT NULL CHECK (origin IN ('worker', 'gateway')),
  turn_id      uuid,                                   -- NULL between turns (background tasks, compaction, notices)
  kind         text NOT NULL,                          -- ThreadEvent.body case, e.g. item_completed
  item_id      text,                                   -- for item_* events
  payload      jsonb NOT NULL,                         -- ThreadEvent.body as protobuf JSON
  raw          jsonb,                                  -- original provider event, kept even when unmapped
  occurred_at  timestamptz NOT NULL,
  recorded_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (thread_id, seq),
  UNIQUE (thread_id, event_id),
  FOREIGN KEY (turn_id, thread_id) REFERENCES turns (id, thread_id),
  CONSTRAINT thread_events_item_id CHECK ((kind LIKE 'item\_%') = (item_id IS NOT NULL))
);
CREATE INDEX thread_events_item ON thread_events (thread_id, item_id) WHERE item_id IS NOT NULL;

-- Projection for the UI: current state of every item, updated in the same transaction as the event.
-- The UI loads items (snapshot), then follows thread_events after max(last_seq).
CREATE TABLE thread_items (
  thread_id       uuid NOT NULL REFERENCES threads (id),
  item_id         text NOT NULL,
  turn_id         uuid,
  parent_item_id  text,
  type            text NOT NULL,                       -- Item.content case, e.g. command_execution
  status          text NOT NULL,                       -- ItemStatus without prefix, e.g. in_progress
  content         jsonb NOT NULL,                      -- Item as protobuf JSON (deltas already applied)
  first_seq       bigint NOT NULL,
  last_seq        bigint NOT NULL,
  PRIMARY KEY (thread_id, item_id),
  FOREIGN KEY (turn_id, thread_id) REFERENCES turns (id, thread_id),
  CONSTRAINT thread_items_seq_order CHECK (last_seq >= first_seq)
);
CREATE INDEX thread_items_order ON thread_items (thread_id, first_seq);
CREATE INDEX thread_items_open ON thread_items (thread_id) WHERE status = 'in_progress';

-- Content larger than a message (tool output, diffs, images). Content-addressed, never truncated.
CREATE TABLE blobs (
  sha256      text PRIMARY KEY CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  size_bytes  bigint NOT NULL CHECK (size_bytes >= 0),
  mime_type   text NOT NULL DEFAULT 'application/octet-stream',
  data        bytea,                                   -- NULL when moved to object storage
  storage_url text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT blobs_one_location CHECK ((data IS NULL) <> (storage_url IS NULL))
);

-- Which journal entries of a worker are already persisted (Welcome cursors).
-- Scoped by journal_id: a reinstalled worker starts a new journal and resends everything (deduplicated by event_id).
CREATE TABLE worker_journal_cursors (
  worker_id    uuid NOT NULL REFERENCES workers (id),
  journal_id   text NOT NULL,
  thread_id    uuid NOT NULL REFERENCES threads (id),
  acked_seq    bigint NOT NULL,
  PRIMARY KEY (worker_id, journal_id, thread_id)
);

-- ---------------------------------------------------------------- lineage invariants

-- Side threads inherit project, owner, tree, placement and runtime from their parent.
-- A fork source must be in the same tree, use the same provider, and fork at a completed turn.
CREATE FUNCTION threads_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  parent threads%ROWTYPE;
  source threads%ROWTYPE;
  source_turn turns%ROWTYPE;
BEGIN
  IF NEW.kind = 'side' THEN
    SELECT * INTO parent FROM threads WHERE id = NEW.parent_thread_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'parent thread % not found', NEW.parent_thread_id USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF parent.archived_at IS NOT NULL THEN
      RAISE EXCEPTION 'parent thread % is archived', parent.id USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.project_id <> parent.project_id OR NEW.owner_user_id <> parent.owner_user_id
       OR NEW.root_thread_id <> parent.root_thread_id OR NEW.depth <> parent.depth + 1 THEN
      RAISE EXCEPTION 'side thread must share project, owner and tree with its parent' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.runtime <> parent.runtime
       OR NEW.worker_id IS DISTINCT FROM parent.worker_id
       OR NEW.workspace_id IS DISTINCT FROM parent.workspace_id
       OR NEW.cwd IS DISTINCT FROM parent.cwd THEN
      RAISE EXCEPTION 'side thread must run on the same worker and directory as its parent' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.fork_source_thread_id IS NOT NULL THEN
    SELECT * INTO source FROM threads WHERE id = NEW.fork_source_thread_id FOR SHARE;
    IF source.root_thread_id <> NEW.root_thread_id THEN
      RAISE EXCEPTION 'fork source must be in the same thread tree' USING ERRCODE = 'check_violation';
    END IF;
    IF source.provider <> NEW.provider THEN
      RAISE EXCEPTION 'fork must keep the provider (% -> %)', source.provider, NEW.provider USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.fork_after_turn_id IS NULL THEN
      -- Pin the fork point now, so the inherited history never changes afterwards.
      SELECT * INTO source_turn FROM turns
       WHERE thread_id = source.id AND status = 'completed' ORDER BY ordinal DESC LIMIT 1;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'fork source % has no completed turn', source.id USING ERRCODE = 'check_violation';
      END IF;
      NEW.fork_after_turn_id := source_turn.id;
    ELSE
      SELECT * INTO source_turn FROM turns WHERE id = NEW.fork_after_turn_id AND thread_id = source.id;
      IF NOT FOUND OR source_turn.status <> 'completed' THEN
        RAISE EXCEPTION 'fork point must be a completed turn of the source thread' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER threads_before_insert BEFORE INSERT ON threads
  FOR EACH ROW EXECUTE FUNCTION threads_before_insert();

-- A thread is pinned for life: provider history lives on that worker, in that directory.
CREATE FUNCTION threads_before_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (NEW.project_id, NEW.owner_user_id, NEW.kind, NEW.parent_thread_id, NEW.root_thread_id, NEW.depth,
      NEW.runtime, NEW.provider, NEW.worker_id, NEW.workspace_id, NEW.cwd,
      NEW.fork_source_thread_id, NEW.fork_after_turn_id)
     IS DISTINCT FROM
     (OLD.project_id, OLD.owner_user_id, OLD.kind, OLD.parent_thread_id, OLD.root_thread_id, OLD.depth,
      OLD.runtime, OLD.provider, OLD.worker_id, OLD.workspace_id, OLD.cwd,
      OLD.fork_source_thread_id, OLD.fork_after_turn_id) THEN
    RAISE EXCEPTION 'thread placement and lineage are immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.provider_thread_id IS NOT NULL AND NEW.provider_thread_id IS DISTINCT FROM OLD.provider_thread_id THEN
    RAISE EXCEPTION 'provider_thread_id is set once' USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;

CREATE TRIGGER threads_before_update BEFORE UPDATE ON threads
  FOR EACH ROW EXECUTE FUNCTION threads_before_update();

-- Fork chain of a thread: itself (level 0, no cap) and every fork source up to the pinned turn.
-- upto_seq is in the source's own seq space (every thread numbers its timeline from 1).
CREATE FUNCTION thread_fork_chain(p_thread_id uuid)
RETURNS TABLE (thread_id uuid, upto_seq bigint, level integer)
LANGUAGE sql STABLE AS $$
  WITH RECURSIVE chain (thread_id, upto_seq, level) AS (
    SELECT p_thread_id, NULL::bigint, 0
    UNION ALL
    SELECT t.fork_source_thread_id, ft.last_seq, chain.level + 1
      FROM chain
      JOIN threads t ON t.id = chain.thread_id
      JOIN turns ft ON ft.id = t.fork_after_turn_id
  )
  SELECT thread_id, upto_seq, level FROM chain
$$;

-- Full visible timeline: inherited fork prefixes (recursively) followed by the thread's own events.
-- Inherited rows keep their origin thread_id, so the UI can mark them.
CREATE FUNCTION thread_timeline(p_thread_id uuid)
RETURNS TABLE (thread_id uuid, seq bigint, turn_id uuid, kind text, item_id text, payload jsonb, occurred_at timestamptz, inherited boolean)
LANGUAGE sql STABLE AS $$
  SELECT e.thread_id, e.seq, e.turn_id, e.kind, e.item_id, e.payload, e.occurred_at, c.level > 0
    FROM thread_fork_chain(p_thread_id) c
    JOIN thread_events e ON e.thread_id = c.thread_id
   WHERE c.upto_seq IS NULL OR e.seq <= c.upto_seq
   ORDER BY c.level DESC, e.seq
$$;

-- Item snapshot for the UI, including inherited items.
-- changed_after_fork: the source item kept changing after the fork point (e.g. a background task);
-- its state at the fork point must be rebuilt from thread_timeline events.
CREATE FUNCTION thread_items_view(p_thread_id uuid)
RETURNS TABLE (thread_id uuid, item_id text, turn_id uuid, parent_item_id text, type text, status text,
               content jsonb, first_seq bigint, last_seq bigint, inherited boolean, changed_after_fork boolean)
LANGUAGE sql STABLE AS $$
  SELECT i.thread_id, i.item_id, i.turn_id, i.parent_item_id, i.type, i.status, i.content, i.first_seq, i.last_seq,
         c.level > 0, c.upto_seq IS NOT NULL AND i.last_seq > c.upto_seq
    FROM thread_fork_chain(p_thread_id) c
    JOIN thread_items i ON i.thread_id = c.thread_id
   WHERE c.upto_seq IS NULL OR i.first_seq <= c.upto_seq
   ORDER BY c.level DESC, i.first_seq
$$;

-- ---------------------------------------------------------------- operations (durability)

-- Outbox of commands for workers (docs/durability.md, 4.2).
CREATE TABLE worker_commands (
  id                 uuid PRIMARY KEY,                   -- = Command.command_id
  worker_id          uuid NOT NULL REFERENCES workers (id),
  thread_id          uuid REFERENCES threads (id),
  turn_id            uuid,
  client_request_id  text UNIQUE,
  kind               text NOT NULL,
  payload            bytea NOT NULL,                     -- protobuf Command
  status             text NOT NULL DEFAULT 'pending'
                       CHECK (status IN ('pending', 'delivered', 'completed', 'failed', 'expired')),
  delivered_epoch    bigint,
  result             jsonb,
  expires_at         timestamptz NOT NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  completed_at       timestamptz,
  FOREIGN KEY (turn_id, thread_id) REFERENCES turns (id, thread_id)
);
CREATE INDEX worker_commands_open ON worker_commands (worker_id, created_at) WHERE status IN ('pending', 'delivered');

-- Provider waiting for a human: tool permission, question, MCP elicitation.
-- May come from a turn, a subagent or a background task after the turn ended (turn_id NULL).
CREATE TABLE interaction_requests (
  id            uuid PRIMARY KEY,                        -- = InteractionRequest.request_id
  thread_id     uuid NOT NULL REFERENCES threads (id),
  turn_id       uuid,
  item_id       text,                                    -- tool / subagent item it belongs to
  kind          text NOT NULL CHECK (kind IN ('permission', 'question', 'elicitation')),
  tool_name     text NOT NULL DEFAULT '',
  request       jsonb NOT NULL,
  status        text NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'allowed', 'declined', 'answered', 'expired', 'cancelled')),
  -- Snapshot of threads.interaction_route when the request arrived.
  routed_to     text NOT NULL CHECK (routed_to IN ('human', 'parent')),
  response      jsonb,
  answered_by   uuid REFERENCES users (id),               -- the user, or
  answered_by_thread_id uuid REFERENCES threads (id),     -- the parent thread's agent (answer_interaction)
  answered_at   timestamptz,
  expires_at    timestamptz,                             -- NULL = waits until answered or the thread stops
  created_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (turn_id, thread_id) REFERENCES turns (id, thread_id),
  CONSTRAINT interaction_requests_answer_time CHECK ((status = 'pending') = (answered_at IS NULL)),
  -- A decision has exactly one author; expiry and cancellation by the system have none.
  CONSTRAINT interaction_requests_answered_by CHECK (
    CASE WHEN status IN ('allowed', 'declined', 'answered')
         THEN (answered_by IS NULL) <> (answered_by_thread_id IS NULL)
         ELSE answered_by_thread_id IS NULL END
  ),
  CONSTRAINT interaction_requests_agent_answer_routed CHECK (answered_by_thread_id IS NULL OR routed_to = 'parent'),
  CONSTRAINT interaction_requests_decision_is_permission CHECK (kind = 'permission' OR status NOT IN ('allowed', 'declined')),
  CONSTRAINT interaction_requests_permission_not_answered CHECK (kind <> 'permission' OR status <> 'answered')
);
CREATE INDEX interaction_requests_pending ON interaction_requests (thread_id) WHERE status = 'pending';

-- Agent bus (docs/agent-bus.md): every tool call an agent makes to coordinate other threads.
-- Native provider subagents are off by default; delegation happens here, as side threads.
-- Idempotent by id (= AgentToolCall.call_id): a resent call returns the stored result.
CREATE TABLE agent_bus_calls (
  id                uuid PRIMARY KEY,
  source_thread_id  uuid NOT NULL REFERENCES threads (id),
  source_turn_id    uuid,                                -- NULL for calls from background work after the turn
  source_item_id    text,
  tool              text NOT NULL CHECK (tool IN ('list_agents', 'spawn_thread', 'send_message', 'wait_threads',
                                                  'get_thread', 'read_thread', 'list_threads', 'interrupt_thread', 'close_thread',
                                                  'list_interactions', 'answer_interaction',
                                                  'schedule_wakeup', 'schedule_recurring', 'list_schedules', 'cancel_schedule',
                                                  'get_goal', 'propose_goal', 'update_goal')),
  arguments         jsonb NOT NULL,
  status            text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'completed', 'failed')),
  result            jsonb,
  error             text,
  -- spawn_thread / send_message: the thread and turn the call started.
  target_thread_id  uuid REFERENCES threads (id),
  target_turn_id    uuid,
  -- Hops of the started turn: hops of the caller's turn + 1 (bounded, stops agent ping-pong).
  hops              smallint CHECK (hops BETWEEN 1 AND 16),
  -- notify: when target_turn finishes, the gateway starts a turn in the source thread with the result.
  notify            boolean NOT NULL DEFAULT false,
  notify_status     text CHECK (notify_status IN ('pending', 'delivered', 'cancelled')),
  notified_turn_id  uuid,
  created_at        timestamptz NOT NULL DEFAULT now(),
  completed_at      timestamptz,
  FOREIGN KEY (source_turn_id, source_thread_id) REFERENCES turns (id, thread_id),
  FOREIGN KEY (target_turn_id, target_thread_id) REFERENCES turns (id, thread_id),
  FOREIGN KEY (notified_turn_id, source_thread_id) REFERENCES turns (id, thread_id),
  CONSTRAINT agent_bus_calls_starts_turn CHECK (
    (tool IN ('spawn_thread', 'send_message')) = (hops IS NOT NULL)
    AND (tool IN ('spawn_thread', 'send_message') OR target_turn_id IS NULL)
  ),
  CONSTRAINT agent_bus_calls_notify CHECK (
    notify = (notify_status IS NOT NULL)
    AND (NOT notify OR tool IN ('spawn_thread', 'send_message'))
    AND ((notify_status = 'delivered') = (notified_turn_id IS NOT NULL))
  ),
  CONSTRAINT agent_bus_calls_result CHECK ((status = 'requested') = (completed_at IS NULL))
);
CREATE INDEX agent_bus_calls_source ON agent_bus_calls (source_thread_id, created_at);
CREATE INDEX agent_bus_calls_target_turn ON agent_bus_calls (target_turn_id) WHERE notify_status = 'pending';

-- Turns started through the bus point at the call; side threads created by agents point at the spawn call.
ALTER TABLE turns ADD FOREIGN KEY (agent_call_id) REFERENCES agent_bus_calls (id);
ALTER TABLE threads ADD FOREIGN KEY (spawned_by_call_id) REFERENCES agent_bus_calls (id);
ALTER TABLE turns ADD FOREIGN KEY (interaction_request_id) REFERENCES interaction_requests (id);

-- Platform schedules (replace provider-native timers): durable, visible, survive restarts.
-- The gateway fires due schedules with a lease (FOR UPDATE SKIP LOCKED) as turns with trigger = schedule.
CREATE TABLE schedules (
  id                  uuid PRIMARY KEY,
  thread_id           uuid NOT NULL REFERENCES threads (id),
  kind                text NOT NULL CHECK (kind IN ('once', 'recurring')),
  prompt              text NOT NULL,
  run_at              timestamptz,                         -- once
  cron                text,                                -- recurring, five fields
  timezone            text NOT NULL DEFAULT 'UTC',
  until               timestamptz,
  max_runs            integer CHECK (max_runs > 0),
  runs                integer NOT NULL DEFAULT 0 CHECK (runs >= 0),
  next_run_at         timestamptz,                         -- NULL once finished
  -- After downtime: run one catch-up turn, or skip missed runs.
  missed_policy       text NOT NULL DEFAULT 'run_once' CHECK (missed_policy IN ('run_once', 'skip')),
  status              text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'completed', 'cancelled')),
  created_by_user_id  uuid REFERENCES users (id),
  created_by_call_id  uuid REFERENCES agent_bus_calls (id),
  hops                smallint NOT NULL DEFAULT 0 CHECK (hops BETWEEN 0 AND 16),
  lease_owner         text,
  lease_until         timestamptz,
  last_turn_id        uuid,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (last_turn_id, thread_id) REFERENCES turns (id, thread_id),
  CONSTRAINT schedules_kind_fields CHECK (
    (kind = 'once' AND run_at IS NOT NULL AND cron IS NULL AND until IS NULL AND max_runs IS NULL)
    OR (kind = 'recurring' AND run_at IS NULL AND cron IS NOT NULL)
  ),
  CONSTRAINT schedules_one_creator CHECK ((created_by_user_id IS NULL) <> (created_by_call_id IS NULL)),
  -- Agents never create open-ended schedules and always extend the chain; users may and do not.
  CONSTRAINT schedules_agent_bounded CHECK (
    created_by_call_id IS NULL OR (hops > 0 AND (kind = 'once' OR until IS NOT NULL OR max_runs IS NOT NULL))
  ),
  CONSTRAINT schedules_user_hops CHECK (created_by_user_id IS NULL OR hops = 0),
  CONSTRAINT schedules_active_has_next CHECK ((status = 'active') = (next_run_at IS NOT NULL))
);
CREATE INDEX schedules_due ON schedules (next_run_at) WHERE status = 'active';
CREATE INDEX schedules_thread ON schedules (thread_id) WHERE status IN ('active', 'paused');

ALTER TABLE turns ADD FOREIGN KEY (schedule_id) REFERENCES schedules (id);

-- Goals (docs/goals.md): owned by the platform, executed by the harness's native goal feature
-- (engine = native: Codex thread/goal, Claude /goal) or by the gateway (engine = platform).
CREATE TABLE goals (
  id                   uuid PRIMARY KEY,
  thread_id            uuid NOT NULL REFERENCES threads (id),
  objective            text NOT NULL,
  condition            text NOT NULL DEFAULT '',           -- verifiable completion condition
  status               text NOT NULL CHECK (status IN ('proposed', 'active', 'paused', 'blocked',
                                                       'budget_limited', 'usage_limited', 'achieved', 'cancelled')),
  engine               text NOT NULL DEFAULT 'native' CHECK (engine IN ('native', 'platform')),
  -- Usage accounting: this thread only, or the whole tree (side threads working for the goal).
  scope                text NOT NULL DEFAULT 'tree' CHECK (scope IN ('thread', 'tree')),
  token_budget         bigint CHECK (token_budget > 0),
  cost_budget_usd      numeric(12, 4) CHECK (cost_budget_usd > 0),
  time_budget_seconds  integer CHECK (time_budget_seconds > 0),
  turn_budget          integer CHECK (turn_budget > 0),
  tokens_used          bigint NOT NULL DEFAULT 0 CHECK (tokens_used >= 0),
  cost_used_usd        numeric(12, 4) NOT NULL DEFAULT 0 CHECK (cost_used_usd >= 0),
  time_used_seconds    integer NOT NULL DEFAULT 0 CHECK (time_used_seconds >= 0),
  turns_used           integer NOT NULL DEFAULT 0 CHECK (turns_used >= 0),
  last_reason          text,                               -- evaluator verdict, blocker, exceeded budget
  native_state         jsonb,                              -- last snapshot from the harness (Codex ThreadGoal, Claude active_goal)
  -- user: from the UI; agent: platform tool; provider: the model used the harness's own goal tool.
  created_by           text NOT NULL CHECK (created_by IN ('user', 'agent', 'provider')),
  created_by_user_id   uuid REFERENCES users (id),
  created_by_call_id   uuid REFERENCES agent_bus_calls (id),
  approved_by          uuid REFERENCES users (id),
  approved_at          timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  finished_at          timestamptz,
  CONSTRAINT goals_creator CHECK (
    (created_by = 'user' AND created_by_user_id IS NOT NULL AND created_by_call_id IS NULL)
    OR (created_by = 'agent' AND created_by_call_id IS NOT NULL AND created_by_user_id IS NULL)
    OR (created_by = 'provider' AND created_by_user_id IS NULL AND created_by_call_id IS NULL)
  ),
  -- Goals not set by the user start as proposed and run only after a user approved them.
  CONSTRAINT goals_approval CHECK (
    created_by = 'user' OR status IN ('proposed', 'cancelled') OR approved_by IS NOT NULL
  ),
  CONSTRAINT goals_approval_time CHECK ((approved_by IS NULL) = (approved_at IS NULL)),
  -- Goals not set by the user are bounded.
  CONSTRAINT goals_agent_budget CHECK (
    created_by = 'user'
    OR token_budget IS NOT NULL OR cost_budget_usd IS NOT NULL OR time_budget_seconds IS NOT NULL OR turn_budget IS NOT NULL
  ),
  CONSTRAINT goals_finished CHECK ((status IN ('achieved', 'cancelled')) = (finished_at IS NOT NULL))
);
-- At most one open goal per thread (same rule as Codex: finish the current goal first).
CREATE UNIQUE INDEX goals_one_open ON goals (thread_id) WHERE status NOT IN ('achieved', 'cancelled');
CREATE INDEX goals_active ON goals (thread_id) WHERE status = 'active';

ALTER TABLE turns ADD FOREIGN KEY (goal_id) REFERENCES goals (id);

CREATE TABLE audit_log (
  id             uuid PRIMARY KEY,
  actor_user_id  uuid REFERENCES users (id),
  action         text NOT NULL,
  target_type    text NOT NULL,
  target_id      uuid,
  details        jsonb NOT NULL DEFAULT '{}',
  created_at     timestamptz NOT NULL DEFAULT now()
);
